mapper.select:
SELECT system_enabled, activity_enabled, task_enabled
FROM user_notification_setting
WHERE username = #{username}

SELECT document_type, title, content, updated_at
FROM app_document
WHERE document_type = #{documentType}

SELECT username, plan_name, status, expire_at, benefits
FROM user_membership
WHERE username = #{username}

SELECT COUNT(*)
FROM user_favorite
WHERE username = #{username}

SELECT id, item_type, title, description, icon_tone, created_at
FROM user_favorite
WHERE username = #{username}
ORDER BY created_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE user_trip_slot
SET status = 'BOOKED',
    reviewed_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND owner_username = #{ownerUsername}
  AND status = 'PENDING'
